import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.sc8Z_ZE3.js";const p=JSON.parse('{"title":"Known limitations","description":"","frontmatter":{},"headers":[],"relativePath":"start/known-limitations.md","filePath":"start/known-limitations.md"}'),r={name:"start/known-limitations.md"};function s(i,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h1><p>Octryx AI 0.0.1-alpha ships with these known limitations. Each one is planned for 0.0.2. Feature pages list their own smaller limits too; see for example the <a href="/docs/review-bot/limits">review bot&#39;s limits</a> and <a href="/docs/start/status">Status and results</a>.</p><h2 id="sensitive-content-handling" tabindex="-1">Sensitive content handling <a class="header-anchor" href="#sensitive-content-handling" aria-label="Permalink to &quot;Sensitive content handling&quot;">​</a></h2><p>See <a href="/docs/security/sensitive-content">Sensitive content handling</a> for how it works.</p><ul><li><strong>Threat model.</strong> The coding-agent gateway protects against accidental leakage by your own coding agent and against prompt injection that arrives in tool results. It does not defend against a deliberately evasive client: Claude Code and Codex are your own programs and can reach any provider directly.</li><li><strong>The gateway forwards a request unchanged or refuses it.</strong> Masking and rerouting apply only to the platform&#39;s own model calls. On the gateway, a kind set to mask, reroute or mask and reroute keeps its gateway default: credentials refused, credential assignments reported, other kinds not acted on. Only a custom content policy that asks to mask or reroute refuses the request (<code>content_handling_gateway_refused</code>).</li><li><strong>Opaque fields are skipped by key name, without validation.</strong> These are provider-signed state and inline media data; see <a href="/docs/security/sensitive-content#the-opaque-key-list">the opaque key list</a>.</li><li><strong>Prompt injection on the gateway</strong> is checked only inside tool results. It is not checked in your own text, in the assistant&#39;s text, in the client&#39;s system prompt or in tool metadata.</li><li><strong>Report de-duplication covers only the platform&#39;s own model calls and is kept in memory.</strong> A platform call does not report a text again that an earlier record of the same process and scope already reported. After a restart that text is reported once more, and a report first found by the final check of the sent bytes is not de-duplicated. The gateway writes a record for every forwarded request with a reported finding.</li></ul><h2 id="work-items-and-pull-requests" tabindex="-1">Work items and pull requests <a class="header-anchor" href="#work-items-and-pull-requests" aria-label="Permalink to &quot;Work items and pull requests&quot;">​</a></h2><ul><li><strong>Pull requests are recorded internally.</strong> A workflow run records the pull request it opens, and while it waits for the merge or decline it asks for a refresh of that record. The refresh reads GitHub and Bitbucket pull requests only, and only while the repository&#39;s connection still serves the host the pull request was recorded on (otherwise <code>host_mismatch</code>). GitLab runs are watched through their own poll and webhook. There is no pull request page and no manual sync or refresh. The pull request reviewer routes were removed; reviewer recommendations and overrides on work items remain.</li><li><strong>A work item and an intake keep the Workspace they were created in.</strong> A change of Workspace is refused (<code>409 workspace_immutable</code>).</li><li><strong>There is no pull request traceability sync for design delivery.</strong> The release and checkpoint trace syncs remain.</li></ul>',7)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
